int main(void) {
    int t[100], n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%d", &t[i]);
    int mini = 0, maxi = 0;
    min_max(t, n, &mini, &maxi);
    printf("%d %d\n", mini, maxi);
    return 0;
}

exercices.solution:
void min_max(int t[], int n, int *min, int *max) {
    *min = *max = t[0];
    for (int i = 1; i < n; i++) {
        if (t[i] < *min)
            *min = t[i];
        if (t[i] > *max)
            *max = t[i];
    }
}
